-- youB — Intelligence Core authenticated role/cross-tenant suite
-- Disposable staging only. This suite never applies migrations and rolls back all fixtures.
begin;
create temp table suite_context(key text primary key, value uuid not null) on commit drop;
do $$ declare t text; begin foreach t in array array['intelligence_signals','intelligence_evidence','intelligence_recommendations','intelligence_interventions','intelligence_actions','intelligence_outcomes','intelligence_recommendation_evidence','knowledge_sources','knowledge_documents'] loop if to_regclass('public.'||t) is null then raise exception 'missing intelligence prerequisite: %', t; end if; end loop; if (select count(*) from auth.users) < 4 then raise exception 'suite requires four auth users'; end if; end $$;
create or replace function pg_temp.try_cross_tenant_signal() returns boolean language plpgsql security invoker as $$ begin begin insert into public.intelligence_signals(organization_id,employee_id,signal_type,source_type) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_b'),'cross','test'); return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_collaborator_insert(kind text) returns boolean language plpgsql security invoker as $$ begin begin if kind='recommendation' then insert into public.intelligence_recommendations(organization_id,employee_id,title) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_a'),'unauthorized'); elsif kind='evidence' then insert into public.intelligence_evidence(organization_id,signal_id,evidence_type,summary,source_type) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='signal_a'),'unauthorized','unauthorized','test'); elsif kind='intervention' then insert into public.intelligence_interventions(organization_id,employee_id,intervention_type,title) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_a'),'unauthorized','unauthorized'); else insert into public.intelligence_outcomes(organization_id,outcome_type) values ((select value from suite_context where key='org_a'),'unauthorized'); end if; return true; exception when others then return false; end; end; $$;
select set_config('request.jwt.claim.sub',(select value::text from suite_context where key='user_4'),false); set local role authenticated;
select jsonb_build_object('cross_tenant_fk_denied',not pg_temp.try_cross_tenant_signal(),'collaborator_recommendation_insert_denied',not pg_temp.try_collaborator_insert('recommendation'),'collaborator_evidence_insert_denied',not pg_temp.try_collaborator_insert('evidence'),'collaborator_intervention_insert_denied',not pg_temp.try_collaborator_insert('intervention'),'collaborator_outcome_insert_denied',not pg_temp.try_collaborator_insert('outcome'),'organization_document_visible',(select count(*)=1 from public.knowledge_documents where access_level='organization'),'management_document_hidden',(select count(*)=0 from public.knowledge_documents where access_level='management'),'restricted_document_hidden',(select count(*)=0 from public.knowledge_documents where access_level='restricted')) as intelligence_rls_result;
reset role; rollback;

